def signal(obs):
    mC = obs.hist('C','mid',60)
    mCx = obs.hist('C.X','mid',60)
    if mC is None or len(mC)<60:
        return {}
    # check nan via != self
    def is_nan(x): return x!=x
    def mom(arr):
        if is_nan(arr[-1]) or is_nan(arr[-51]):
            return 0
        return arr[-1]-arr[-51]
    momC = mom(mC)
    momCx = mom(mCx)
    sig=0
    if momC>0 and momCx>0:
        sig=1
    elif momC<0 and momCx<0:
        sig=-1
    else:
        sig=0
    targets={}
    if sig!=0:
        targets['C']= sig*0.9
        targets['C.X']= sig*0.9
    else:
        targets['C']=0
        targets['C.X']=0
    return targets

def signal(obs):
    def is_nan(x): return x!=x
    mC = obs.hist('C','mid',60)
    mCx = obs.hist('C.X','mid',60)
    if mC is None or len(mC)<60:
        return {}
    # use average of C and C.X to reduce noise
    # compute past return 50
    if is_nan(mC[-1]) or is_nan(mC[-51]) or is_nan(mCx[-1]) or is_nan(mCx[-51]):
        return {}
    avg_now = (mC[-1]+mCx[-1])/2
    avg_past = (mC[-51]+mCx[-51])/2
    mom = avg_now - avg_past
    # scale: vol per 50 steps ~ 1.4 * sqrt(50) ~ 10 ; so normalize
    # map mom to [-1,1] via tanh
    # simple: target = clip(mom/20, -1,1)
    sig = mom/20.0
    if sig>1: sig=1
    if sig<-1: sig=-1
    # deadzone small
    if abs(sig)<0.15:
        sig=0
    return {'C': sig, 'C.X': sig}

