def corr(a,b):
    m=np.isfinite(a) & np.isfinite(b)
    if np.sum(m)<30:
        return float('nan')
    a=a[m]; b=b[m]
    am=a.mean(); bm=b.mean()
    denom=math.sqrt(((a-am)**2).sum()*((b-bm)**2).sum())
    if denom==0: return 0.0
    return float(((a-am)*(b-bm)).sum()/denom)

res={}
for horizon in [5,10,20,50,100]:
    for asset in ['A','B','C','IDX','C.X','B.X','A.X']:
        mid=H[asset]['mid']
        past = mid[horizon:] - mid[:-horizon]
        # correlate past with future horizon return, offset by horizon
        # need aligned: past[t] = mid[t] - mid[t-h], future[t]=mid[t+h]-mid[t]
        # So create arrays length N-2h
        if len(mid) <= 2*horizon+10:
            continue
        past_aligned = mid[horizon:-horizon] - mid[:-2*horizon]
        future = mid[2*horizon:]-mid[horizon:-horizon]
        c = corr(past_aligned, future)
        res[f"{asset}_h{horizon}"]=round(c,3)

# also check mid change vs signed volume / imbalance
for asset in ['A','B','C','IDX']:
    mid=H[asset]['mid']
    for h in [10,50]:
        fut = mid[h:]-mid[:-h]
        imb = H[asset]['imbalance'][:-h]
        sv = H[asset]['signed_volume'][:-h]
        res[f"{asset}_imb_vs_fut{h}"]=round(corr(imb,fut),3)
        res[f"{asset}_sv_vs_fut{h}"]=round(corr(sv,fut),3)

result=res

def signal(obs):
    h = 50
    # histories
    c = obs.hist('C', 'mid', h+1)
    cx = obs.hist('C.X', 'mid', h+1)
    if len(c) < h+1:
        return {}
    # get now / past with NaN handling, averaging C and C.X for cleaner signal but trading only C (0 bps)
    now_c = c[-1]
    past_c = c[0]
    # cx may be shorter or contain NaN
    try:
        now_cx = cx[-1] if len(cx) >= h+1 else float('nan')
        past_cx = cx[0] if len(cx) >= h+1 else float('nan')
    except:
        now_cx = float('nan')
        past_cx = float('nan')
    # average where available
    if now_c == now_c and now_cx == now_cx:
        now = 0.5*(now_c + now_cx)
    elif now_c == now_c:
        now = now_c
    elif now_cx == now_cx:
        now = now_cx
    else:
        return {}
    if past_c == past_c and past_cx == past_cx:
        past = 0.5*(past_c + past_cx)
    elif past_c == past_c:
        past = past_c
    elif past_cx == past_cx:
        past = past_cx
    else:
        return {}
    if now != now or past != past:
        return {}
    ret = now - past
    # normalise: mean |ret| ~16-17, so /22 gives ~0.75 typical, clipped
    alpha = ret / 22.0
    if alpha > 1: alpha = 1
    if alpha < -1: alpha = -1
    # dead-zone to cut whipsaw and save spread/fees
    if abs(alpha) < 0.13:
        alpha = 0.0
    # simple hysteresis to avoid rapid flips on small ret
    prev = obs.state.get('prev', 0.0)
    # if we would flip sign on a small move, damp it
    if prev != 0 and alpha != 0 and (prev > 0) != (alpha > 0) and abs(ret) < 8:
        alpha = 0.0
    obs.state['prev'] = alpha
    # trade only primary listing to avoid 3bps taker fee on C.X
    return {'C': float(alpha)}

