def signal(obs):
    out = {}
    for a in ['C','C.X']:
        try:
            m = obs.hist(a, 'mid', 60)
            if len(m) < 60 or np.isnan(m).any():
                continue
            past = m[-1] - m[0]
            # normalize by recent vol
            rets = np.diff(m)
            vol = np.nanstd(rets) + 1e-9
            z = past / (vol * 7.0)  # ~ sqrt(60)? scale
            # clip
            if z > 1: z = 1
            if z < -1: z = -1
            out[a] = float(z)
        except Exception:
            continue
    return out

def signal(obs):
    # IDX vs basket mean reversion
    try:
        a = obs.last('A','mid'); b = obs.last('B','mid'); c = obs.last('C','mid'); idx = obs.last('IDX','mid')
        syn = 0.3333*a + 0.6667*b + 0.1667*c
        basis = idx - syn
        # scale: std ~5
        z = -basis / 8.0
        if z > 1: z = 1
        if z < -1: z = -1
        if abs(z) < 0.2:
            z = 0
        return {'IDX': float(z), 'A': float(-z*0.3), 'B': float(-z*0.6), 'C': float(-z*0.15)}
    except Exception:
        return {}

def signal(obs):
    out = {}
    try:
        for p,q,w in [('A','A.X',1),('B','B.X',1),('C','C.X',1)]:
            a = obs.last(p,'mid'); b = obs.last(q,'mid')
            s = a - b
            if np.isnan(s):
                continue
            # need std estimate; use fixed from research
            sd = {'A':2.0,'B':3.2,'C':4.3}[p]
            z = -s / (2*sd)
            if z>1: z=1
            if z<-1: z=-1
            if abs(z)<0.25: z=0
            out[p]=float(z)
            out[q]=float(-z)
    except Exception:
        pass
    return out

def signal(obs):
    out = {}
    for a, lb in [('C', 60),]:
        try:
            m = obs.hist(a, 'mid', lb+10)
            if len(m) < lb+10 or np.isnan(m).any():
                continue
            past = m[-1] - m[-lb]
            v = np.nanstd(np.diff(m)) + 1e-9
            z = past / (v * 8.0)
            if z > 1: z = 1
            if z < -1: z = -1
            if abs(z) < 0.2: z = 0
            out[a] = float(z)
        except Exception:
            continue
    return out

def signal(obs):
    # C momentum + imbalance combo
    try:
        m = obs.hist('C', 'mid', 70)
        imb = obs.hist('C', 'imbalance', 10)
        if len(m) < 70 or np.isnan(m).any():
            return {}
        past = m[-1] - m[-60]
        v = np.nanstd(np.diff(m)) + 1e-9
        z_mom = past / (v * 8.0)
        im = float(np.nanmean(imb[-5:])) if len(imb)>=5 else 0.0
        if np.isnan(im): im = 0.0
        z = z_mom + 0.5*im
        if z > 1: z = 1
        if z < -1: z = -1
        if abs(z) < 0.2: z = 0
        return {'C': float(z)}
    except Exception:
        return {}

def signal(obs):
    # smoothed momentum using state EWMA
    try:
        m = obs.hist('C', 'mid', 70)
        if len(m) < 70 or np.isnan(m).any():
            st = obs.state
            return {'C': float(st.get('pos', 0.0))}
        past = m[-1] - m[-60]
        v = np.nanstd(np.diff(m)) + 1e-9
        z = past / (v * 8.0)
        if z > 1: z = 1
        if z < -1: z = -1
        if abs(z) < 0.25: z = 0
        st = obs.state
        prev = float(st.get('pos', 0.0))
        # only update if change is material to cut turnover
        if abs(z - prev) < 0.3:
            z = prev
        st['pos'] = float(z)
        return {'C': float(z)}
    except Exception:
        return {}

def signal(obs):
    try:
        m = obs.hist('C', 'mid', 90)
        if len(m) < 90 or np.isnan(m).any():
