def signal(obs):
    targets = {}
    for a in ['A.X','B.X','C.X']:
        targets[a] = 0.0

    # --- micro for A,B,C (primary B, A secondary, C small) ---
    for asset in ['A','B','C']:
        try:
            imb = obs.last(asset, 'imbalance')
            if not np.isfinite(imb):
                targets[asset] = 0.0
                continue
            sv = obs.last(asset, 'signed_volume')
            # signed volume z-score
            zsv = 0.0
            try:
                hs = obs.hist(asset, 'signed_volume', 60)
                if hs is not None and np.sum(np.isfinite(hs)) > 40 and np.isfinite(sv):
                    vs = np.nanstd(hs[np.isfinite(hs)])
                    if np.isfinite(vs) and vs > 0.5:
                        zsv = float(sv / vs)
                    else:
                        zsv = 0.0
                else:
                    zsv = 0.0
            except:
                zsv = 0.0
            score = float(imb)
            # sv agreement tilt
            if np.isfinite(zsv) and abs(zsv) > 0.8 and abs(score) > 0.05:
                if np.sign(zsv) != np.sign(score):
                    score *= 0.55
                else:
                    score *= 1.12
                    if score > 1: score = 1
                    if score < -1: score = -1
            # deadzone and scaling - reduce turnover
            if abs(score) < 0.20:
                targets[asset] = 0.0
            else:
                strength = (abs(score) - 0.20) / 0.40
                if strength > 1: strength = 1
                if strength < 0: strength = 0
                strength = 0.45 + 0.55*strength
                # weight by asset reliability recent: B strongest, A medium, C weak
                w = 1.0 if asset=='B' else (0.7 if asset=='A' else 0.5)
                targets[asset] = float(np.clip(np.sign(score)*strength*w, -1, 1))
                # spread filter
                try:
                    sp = obs.last(asset, 'spread')
                    if np.isfinite(sp) and sp > 16:
                        targets[asset] *= 0.6
                except:
                    pass
            # momentum overlay for B only (stable)
            if asset == 'B':
                try:
                    hist = obs.hist(asset, 'mid', 160)
                    if hist is not None and len(hist) >= 100:
                        H = 30
                        past = hist[-1] - hist[-1-H]
                        a = hist[-81:-1]
                        b = hist[-81-H:-1-H]
                        mask = np.isfinite(a) & np.isfinite(b)
                        if np.sum(mask) > 50:
                            vol = np.std(a[mask] - b[mask])
                            if np.isfinite(vol) and vol > 5:
                                z = past / vol
                                if abs(z) > 1.2:
                                    m_strength = min(1.0, 0.5 + 0.35*(abs(z)-1.2))
                                    m_sig = 1.0 if z>0 else -1.0
                                    # imbalance confirmation
                                    if np.isfinite(imb) and np.sign(m_sig) != np.sign(imb) and abs(imb) > 0.25:
                                        m_strength *= 0.6
                                    # blend micro and momentum 50/50
                                    cur = targets[asset]
                                    blended = 0.5*cur + 0.5*m_sig*m_strength
                                    targets[asset] = float(np.clip(blended, -1, 1))
                                    if abs(blended) < 0.18:
                                        targets[asset] = 0.0
                except:
