                    dev_hist = hIDX - syn_hist
                    mask = np.isfinite(dev_hist)
                    if np.sum(mask) > 80:
                        # use last 100
                        vals = dev_hist[mask]
                        if len(vals) >= 100:
                            vals = vals[-100:]
                        dvol = float(np.std(vals))
                        if np.isfinite(dvol) and dvol > 5:
                            arb_z = float(dev / dvol)
                            if abs(arb_z) > 1.7:
                                s = min(1.0, 0.40 + 0.30*(abs(arb_z)-1.7))
                                arb_target = (-1.0 if arb_z>0 else 1.0)*s
                                arb_active = True
            except:
                arb_active = False
        # decide IDX target
        if arb_active and abs(arb_z) > 2.4:
