                        vol = np.std(a[mask]-b[mask])
                        if np.isfinite(vol) and vol > 4:
                            z = past/vol
                            if abs(z) > 1.0:
                                mom_strength = min(1.0, 0.5+0.30*(abs(z)-1.0))
                                mom_sig = 1.0 if z>0 else -1.0
            except:
                mom_sig = 0.0
