                pass
            combined = 0.65*mom_sig*mom_strength + 0.45*np.clip(micro_score,-1,1)
            if arb_active:
                # blend weak arb
                w_arb = 0.65
                combined = w_arb*arb_target + (1-w_arb)*combined
            combined = float(np.clip(combined,-1,1))
