    if n < 60:
        return {}
    import math
    # build diff array skipping NaN at ends by forward fill simple
    # compute rolling mean/std over last 250 diffs
    s = 0.0; s2 = 0.0; cnt = 0
    diffs = []
    for k in range(n):
        av = aM[k]; bv = bM[k]; cv = cM[k]; iv = iM[k]
        # NaN check: NaN != NaN
        if av != av or bv != bv or cv != cv or iv != iv:
            diffs.append(float('nan'))
        else:
            d = iv - (0.3333*av + 0.6667*bv + 0.1667*cv)
            diffs.append(d)
    # use last 250 finite
    window = diffs[-250:] if len(diffs) >= 250 else diffs
    tot = 0.0; tot2 = 0.0; c = 0
