def corr(x,y):
    m=np.isfinite(x)&np.isfinite(y)
    if m.sum()<100:
        return float('nan')
    xm=x[m]-np.mean(x[m]); ym=y[m]-np.mean(y[m])
    return float(np.sum(xm*ym)/np.sqrt(np.sum(xm*xm)*np.sum(ym*ym)))
