def signal(obs):
    targets={}
    for a in ['A','B','C','IDX','A.X','B.X','C.X']:
        targets[a]=0.0
    def mom(asset, H, TH, vol_floor):
        try:
            hist=obs.hist(asset,'mid',260)
            if hist is None or len(hist)<H+130:
                return 0.0
            if not np.isfinite(hist[-1]) or not np.isfinite(hist[-1-H]):
                return 0.0
            past=hist[-1]-hist[-1-H]
            a=hist[-121:-1]
            b=hist[-121-H:-1-H]
            mask=np.isfinite(a)&np.isfinite(b)
            if np.sum(mask)<80:
                return 0.0
            vol=np.std(a[mask]-b[mask])
            if not np.isfinite(vol) or vol < vol_floor:
                return 0.0
            z=past/vol
            if not np.isfinite(z) or abs(z) < TH:
                return 0.0
            strength=0.5+0.5*min(1.0,(abs(z)-TH))
            strength=max(0.0,min(1.0,strength))
            return float((1.0 if z>0 else -1.0)*strength)
        except:
            return 0.0
    targets['C.X']=mom('C.X',20,1.3,8.0)
    targets['A.X']=mom('A.X',20,1.3,8.0)
    targets['A']=0.0
    targets['B']=0.0
    targets['C']=0.0
    targets['IDX']=0.0
    targets['B.X']=0.0
    return targets

