def trigger_rate(asset, Hv, TH, vol_floor):
    m=H[asset]['mid']
    n=len(m)
    cnt=0
    tot=0
    for t in range(3000, n):
        past=m[t]-m[t-Hv]
        a=m[t-120:t]
        b=m[t-120-Hv:t-Hv]
        mask=np.isfinite(a)&np.isfinite(b)
        if np.sum(mask)<80:
            continue
        vol=np.std(a[mask]-b[mask])
        if not np.isfinite(vol) or vol < vol_floor:
            continue
        tot+=1
        z=past/vol
        if abs(z)>=TH:
            cnt+=1
    return (cnt,tot,cnt/max(1,tot))

