def signal(obs):
    # simple cross-exchange arbitrage
    # assets: A, A.X, B, B.X, C, C.X
    # get mids
    mid = {}
    for a in ['A','A.X','B','B.X','C','C.X']:
        try:
            mid[a] = obs.last(a, 'mid')
        except:
            mid[a] = None
    # initialize targets
    targets = {}
    # helper
    def set_pair(asset1, asset2, diff, thresh, mult=0.8):
        if mid[asset1] is None or mid[asset2] is None:
            return
        d = mid[asset1] - mid[asset2]
        if d > thresh:
            targets[asset1] = targets.get(asset1, 0.0) - mult
            targets[asset2] = targets.get(asset2, 0.0) + mult
        elif d < -thresh:
            targets[asset1] = targets.get(asset1, 0.0) + mult
            targets[asset2] = targets.get(asset2, 0.0) - mult
        else:
            # keep existing? set to 0 if no signal
            pass
