def signal(obs):
    st = obs.state
    h = obs.hist('C.X', 'mid', 30)
    if len(h) < 25:
        return {}
    now = float(h[-1])
    ago = float(h[-21])
    if not (now == now and ago == ago):
        return {}
    sig = now - ago
    raw = sig / 50.0
    if raw > 1.0:
        raw = 1.0
    if raw < -1.0:
        raw = -1.0
    prev = float(st.get('p', 0.0))
    if abs(sig) < 15:
        if prev != 0.0 and (sig * prev) > 0 and abs(sig) > 5:
            raw = prev
        else:
            raw = 0.0
    sm = 0.7 * prev + 0.3 * raw
    st['p'] = sm
    t = sm
    if abs(t) < 0.2:
        t = 0.0
    return {'C': float(t)}

