def lead_lag(a,b,lag):
    ma = H[a]['mid']
    mb = H[b]['mid']
    # compute return of b at t+lag vs a return at t
    ra = np.diff(ma)
    rb = np.diff(mb)
    if len(ra) < lag+1:
