def signal(obs):
    s=obs.state
    if "p" not in s: s["p"]={}
    if "e" not in s: s["e"]={}
    def gm(a):
        h=obs.hist(a,"mid",1)
        if len(h)==0: return None
        v=h[-1]
        if v!=v: return None
        return float(v)
    mA=gm("A"); mB=gm("B"); mC=gm("C"); mI=gm("IDX")
    if None in (mA,mB,mC,mI):
        return {}
    syn=0.3333*mA+0.6667*mB+0.1667*mC
    prem=mI - syn
    hA=obs.hist("A","mid",80); hB=obs.hist("B","mid",80); hC=obs.hist("C","mid",80); hI=obs.hist("IDX","mid",80)
    sd=28.0
    if len(hA)>=80:
        syn_h=0.3333*hA+0.6667*hB+0.1667*hC
        prem_h=hI-syn_h
        sd=float(np.nanstd(prem_h))
        if sd!=sd or sd<10: sd=28.0
        if sd>50: sd=50
    z=prem/sd
    # thresholds
    thr=1.2
    # IDX arbitrage
    idx_sig=0
    if abs(z)>=thr:
        if z>3: z=3
        if z<-3: z=-3
        mag=(abs(z)-thr)/(3-thr)
        idx_sig = -(1 if z>0 else -1)*mag
    # momentum overlay on A and B (small)
    mom_sig={}
    for a in ["A","B"]:
        h=obs.hist(a,"mid",60)
        if len(h)>=40:
            cur=h[-1]; lag=h[-21]
            if cur==cur and lag==lag:
                raw=(cur-lag)/15.0  # scale ~15 cents ~ 1
                if raw>1: raw=1
                if raw<-1: raw=-1
                # ema
                prev=s["e"].get(a,0)
                ema=0.3*raw+0.7*prev
                s["e"][a]=ema
                if abs(ema)>0.25:
                    mom_sig[a]=ema*0.25  # small weight
    # combine: arbitrage + mom
    arb={"IDX":idx_sig, "A": -idx_sig*0.3333, "B": -idx_sig*0.6667, "C": -idx_sig*0.1667}
    # note: idx_sig negative when prem positive => A arb = positive
    combined={}
    for k in ["IDX","A","B","C"]:
