# 1) imbalance reversal/momentum IC 50-step fwd
def ic_imb(asset, lag=0):
    imb=H[asset]['imbalance']
    mid=H[asset]['mid']
    fwd=np.zeros(N)
    for t in range(N-50):
        if np.isfinite(mid[t+50]) and np.isfinite(mid[t]):
            fwd[t]=mid[t+50]-mid[t]
    # align
    valid=np.isfinite(imb) & np.isfinite(fwd)
    # also need not nan
    # if lag >0 shift imb
    if lag>0:
        imb_s=np.roll(imb, lag)
        valid=np.isfinite(imb_s) & np.isfinite(fwd)
        c=np.corrcoef(imb_s[valid], fwd[valid])[0,1]
        # Spearman approx
        return float(c)
    else:
        c=np.corrcoef(imb[valid], fwd[valid])[0,1]
        return float(c)

