        m_a = obs.hist('A', 'mid', lookback)
        m_b = obs.hist('B', 'mid', lookback)
        m_c = obs.hist('C', 'mid', lookback)
    except Exception:
        return {}
    if len(m_idx) < lookback:
        return {}
    basket = wa * m_a + wb * m_b + wc * m_c
    diff = m_idx - basket
    if len(diff) <= window + 1:
        return {}
    mean = np.nanmean(diff[-window-1:-1])
    std = np.nanstd(diff[-window-1:-1])
    if np.isnan(mean) or np.isnan(std) or std == 0:
        return {}
    current = diff[-1]
    z = (current - mean) / std
    spread_idx = obs.last('IDX', 'spread')
    spread_a = obs.last('A', 'spread')
    spread_b = obs.last('B', 'spread')
    spread_c = obs.last('C', 'spread')
    denom = wa + wb + wc
    cost = (spread_idx + spread_a * wa + spread_b * wb + spread_c * wc) / denom
    if abs(z) > 1.5 and abs(z) * std > cost:
