def signal(obs):
    targets = {}
    wa, wb, wc = 0.3333, 0.6667, 0.1667
    lookback = 500
    window = 300
    try:
        m_idx = obs.hist('IDX', 'mid', lookback)
        m_a = obs.hist('A', 'mid', lookback)
        m_b = obs.hist('B', 'mid', lookback)
        m_c = obs.hist('C', 'mid', lookback)
    except Exception:
        return {}
    if len(m_idx) < lookback:
        return {}
    basket = wa * m_a + wb * m_b + wc * m_c
    diff = m_idx - basket
    if len(diff) <= window + 1:
        return {}
    mean = np.nanmean(diff[-window-1:-1])
    std = np.nanstd(diff[-window-1:-1])
    if np.isnan(mean) or np.isnan(std) or std == 0:
        return {}
    current = diff[-1]
    z = (current - mean) / std
    # spread cost
    spread_idx = obs.last('IDX','spread')
    spread_a = obs.last('A','spread')
    spread_b = obs.last('B','spread')
    spread_c = obs.last('C','spread')
    denom = wa + wb + wc
    # cost to close arb: approx half spread of each
    cost = (spread_idx/2 + (spread_a*wa+spread_b*wb+spread_c*wc)/2)/denom
    # tighten threshold
    if abs(z) > 2.0 and abs(z)*std > cost*2:
        mag = min(1.0, (abs(z)-1.5)/2.5)  # max 1
        if z > 0:
            targets['IDX'] = -mag
            targets['A'] = mag*wa/(wa+wb+wc)
            targets['B'] = mag*wb/(wa+wb+wc)
            targets['C'] = mag*wc/(wa+wb+wc)
        else:
            targets['IDX'] = mag
            targets['A'] = -mag*wa/(wa+wb+wc)
            targets['B'] = -mag*wb/(wa+wb+wc)
            targets['C'] = -mag*wc/(wa+wb+wc)
    out={}
    for k,v in targets.items():
        if abs(v)>1: v = max(min(v,1),-1)
        out[k]=float(v)
    return out

