        t = 500
        while t < n-60:
            p = m[t]
            pp = m[t-L]
            f = m[t+50]
            if p==p and pp==pp and f==f:
                xs.append(p-pp)
                ys.append(f-p)
            t += 10
        if len(xs)>10:
            xa = np.array(xs); ya = np.array(ys)
