                c = float(np.mean((xa-xm)*(ya-ym))/(sx*sy))
            else:
                c = 0.0
            result[a+'_L'+str(L)] = [round(c,4), len(xs)]
        else:
            result[a+'_L'+str(L)] = [0,0]

